SourceCode.Declaration:
/// <summary>
/// Service class for fleet vehicle operations.
/// </summary>
public class FmVehicleService
{
    FmVehicle vehicle;
}

Method.Source:
public void run()
{
    FmVehicle v;
    select firstOnly v
        where v.VIN != '';
    Info(strFmt("@Fleet:Found", v.RecId));
}

public static FmVehicleService construct()
{
    return new FmVehicleService();
}

/// <summary>
/// Delegate the L2-event-handler-basic eval case subscribes to. Without it the
/// generated handler is metadata-valid and still fails to compile —
/// delegateStr() is checked by the X++ compiler, so an eval case that names a
/// delegate nothing declares can never prove the scaffolder right.
/// </summary>
delegate void OnInitialized(XppPrePostArgs _args)
{
}
